using System;using System.Linq;using BossRush;using ItemStatsSystem;using Duckov.ItemUsage;using HarmonyLib;
internal static class Program{
 private static int checks;internal static void Check(bool value,string name){checks++;if(!value)throw new Exception(name);}
 private static Item Make(int type,params UsageBehavior[] behaviors){var x=new Item{TypeID=type};x.UsageUtilities.behaviors.AddRange(behaviors);return x;}
 private static CharacterMainControl Player(){var p=new CharacterMainControl();CharacterMainControl.Main=p;return p;}
 private static void Hooks(Harmony h){foreach(var type in typeof(Program).Assembly.GetTypes().Where(t=>t.Namespace=="BossRush"&&t.Name.StartsWith("CoopWaylayerClaim")&&t.Name.EndsWith("Hook")))h.CreateClassProcessor(type).Patch();}
 public static int Main(string[] args){try{Native.Install(args[0]);var h=new Harmony("BossRush.Tests.WaylayerClaimUse.Gates");Hooks(h);
  foreach(string marker in new[]{"claim-private-id","refund-private-id","{world-ticket}"}){
   var p=Player();SkyIslandFieldcraft.Current=new SkyIslandFieldcraft();var x=Make(BossRushItemIds.SkyIslandHomecomingBento,new FoodDrink(),new Drug{healValue=15},new SkyIslandFieldcraftUsage{buff=(int)SkyIslandFieldBuff.Meal});x.Root=p.CharacterItem;x.Marker=marker;int onUse=0,onStatic=0,onUsed=0; x.onUse+=(i,u)=>onUse++;Item.onUseStatic=(i,u)=>onStatic++;UsageUtilities.OnItemUsedStaticEvent=i=>onUsed++;
   Check(!x.UsageUtilities.IsUsable(x,p),"locked original not usable at UI query");p.UseItem(x);Check(p.Started==0&&p.CurrentHoldItemAgent==null,"locked pack original cannot start native use");
   x.Use(p);Check(onUse==0&&onStatic==0&&p.Energy==0,"direct Item.Use rejects before user events");
   x.UsageUtilities.Use(x,p);Check(p.Energy==0&&onUsed==0&&x.UsageUtilities.OnItemUsedEvent.Calls==0,"direct Utilities.Use rejects effects and completion events");
   x.UsageUtilities.behaviors[0].Use(x,p);Check(p.Energy==0&&p.Water==0,"direct Behavior.Use rejects effect");
   p.useItemAction.SetUseItem(x);p.useItemAction.Finish();Check(x.StackCount==1&&!x.IsBeingDestroyed&&p.Health.CurrentHealth==20,"actual finish cannot consume locked original even when called directly");
   x.Marker="";p.UseItem(x);Check(p.Started==1&&p.CurrentHoldItemAgent.Item==x,"unlock restores native start");p.useItemAction.Tick(2);Check(x.StackCount==0&&p.Energy==35&&p.Water==20&&p.Health.CurrentHealth==35&&onUse==1&&onStatic==1&&onUsed==1&&SkyIslandFieldcraft.Current.Applied==1,"unlock restores exact bento effects/events/one consumption");Check(!p.useItemAction.Running&&p.CurrentHoldItemAgent==null,"actual update and stop return agent after unlocked use");
  }
  {var p=Player();p.IsMainCharacter=false;var x=Make(BossRushItemIds.SkyIslandStarmossSalve,new Drug{healValue=40});x.Root=p.CharacterItem;x.Marker="pending-non-main-original";p.UseItem(x);Check(p.Started==0,"non-main native start also rejects locked exact item");}
  {var p=Player();var x=Make(BossRushItemIds.SkyIslandStarmossSalve,new Drug{healValue=40});x.Root=p.CharacterItem;p.UseItem(x);x.Marker="publication-became-pending-during-use";p.useItemAction.Tick(2);Check(x.StackCount==1&&p.Health.CurrentHealth==20,"started before lock still blocked at actual finish");Check(!p.useItemAction.Running&&p.CurrentHoldItemAgent==null,"actual update still stops and returns held pending original");x.Marker="";p.UseItem(x);p.useItemAction.Tick(2);Check(x.StackCount==0&&p.Health.CurrentHealth==60,"unlocked salve uses full actual Drug IL once");}
  {var p=Player();SkyIslandFieldcraft.Current=new SkyIslandFieldcraft();var x=Make(BossRushItemIds.SkyIslandWindLantern,new SkyIslandFieldcraftUsage{buff=(int)SkyIslandFieldBuff.Lantern});x.Root=p.CharacterItem;x.Marker="pending-lantern";p.useItemAction.SetUseItem(x);p.useItemAction.Finish();Check(x.StackCount==1&&SkyIslandFieldcraft.Current.Applied==0,"pending wind lantern neither applies nor consumes");x.Marker="";p.UseItem(x);p.useItemAction.Tick(2);Check(x.StackCount==0&&SkyIslandFieldcraft.Current.Applied==1,"unlocked lantern executes linked production OnUse and consumes once");}
  {var p=Player();var x=Make(123,new FoodDrink());x.Root=p.CharacterItem;x.UsageUtilities.useDurability=true;x.UsageUtilities.durabilityUsage=4;x.Marker="pending-durable";x.UsageUtilities.Use(x,p);Check(x.Durability==100,"direct utilities pending durability preserved");x.Marker="";x.Use(p);Check(x.Durability==96&&p.Energy==35,"ordinary unmarked direct use retains actual durability behavior");}
  {var p=Player();var x=Make(124,new FoodDrink());x.Stackable=false;x.Marker="pending-single-tree";p.useItemAction.SetUseItem(x);p.useItemAction.Finish();Check(!x.Destroyed&&!x.IsBeingDestroyed,"locked non-stack tree not destroyed by actual finish");x.Marker="";p.useItemAction.Finish();Check(x.Destroyed&&x.IsBeingDestroyed,"ordinary non-stack original native destruction retained");}
  Check(CoopWaylayerClaims.Locked(null)==false,"null uses shared ordinary gate unchanged");Console.WriteLine("WaylayerClaimUse PASS "+checks+" assertions; full official IL preserved="+Native.Preserved);return 0;
 }catch(Exception e){Console.WriteLine(e);return 1;}}
}
